const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
const isAdmin=u=>['admin','superadmin'].includes(u?.role),isSuperAdmin=u=>u?.role==='superadmin';
const canManageAccount=(actor,target)=>isSuperAdmin(actor)||(isAdmin(actor)&&target.role==='volunteer');
const roleLabel=role=>({superadmin:'Superadmin',admin:'Styrelse',volunteer:'Volontär'}[role]||role);
let state=null,view='schedule',offset=0,filter='all',mutationVersion=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cat=`<svg class="cat" viewBox="0 0 200 150" fill="none" aria-hidden="true"><path d="M49 101C35 82 38 57 49 44L47 15 77 34C91 30 110 30 124 34L153 15 152 46C164 61 165 85 151 103" fill="#d4ddc4" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/><path d="M57 100C22 123 54 145 103 139C154 147 181 119 149 101" fill="#d4ddc4" stroke="currentColor" stroke-width="3"/><path d="M30 128C6 132 9 91 29 102" stroke="currentColor" stroke-width="6" stroke-linecap="round"/><path d="M65 67Q73 60 81 67M117 67Q125 60 133 67M94 80L101 85 108 80M101 85V91M101 91Q92 98 86 91M101 91Q110 98 116 91M45 78L72 82M44 90L72 87M130 82L158 78M131 88L158 92M78 115V132M124 115V132" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg>`;
const brand=`<div class="brand">${cat}<span>Katthemmet</span></div>`;
const dateStr=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fmt=(date,options={day:'numeric',month:'long'})=>new Date(date+'T12:00').toLocaleDateString('sv-SE',options);
function week(){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7+offset*7);return Array.from({length:7},(_,i)=>{const x=new Date(d);x.setDate(x.getDate()+i);return dateStr(x)})}
function weekNumber(date){const d=new Date(date+'T12:00');d.setDate(d.getDate()+3-(d.getDay()+6)%7);const first=new Date(d.getFullYear(),0,4);return 1+Math.round(((d-first)/86400000-3+(first.getDay()+6)%7)/7)}
const staffed=s=>!s.cancelled&&s.booked>=s.minimum_staff;
function needsStaffing(s,now=new Date()){const start=new Date(s.date+'T'+s.start),limit=new Date(now);limit.setDate(limit.getDate()+7);return !s.cancelled&&s.booked<s.minimum_staff&&start>now&&start<=limit}
const staffing=s=>s.cancelled?(s.kind==='event'?'Inställd händelse':'Inställt pass'):`${s.booked} anmälda${s.booked>=7?' · Rek. högst 7':''} · ${staffed(s)?'Minst 2 uppnått':`${s.minimum_staff-s.booked} till behövs`}`;
const past=s=>new Date(s.date+'T'+s.start)<=new Date();
async function api(url,method='GET',data){if(method!=='GET')mutationVersion++;try{const r=await fetch('/api/'+url,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const p=await r.json();if(!r.ok){if(r.status===401&&url!=='login'){state=null;if(modal.open)modal.close();render()}throw Object.assign(Error(p.error),{code:p.code})}return p}finally{if(method!=='GET')mutationVersion++}}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function login(){app.innerHTML=`<div class="login"><section class="login-art">${brand}<div><div class="eyebrow" style="color:#c8d6be">EN LITEN INSATS. EN STOR SKILLNAD.</div><h1>Fler trygga stunder.<br>Fler spinnande katter.</h1><p>Här planerar vi tillsammans vardagen på katthemmet.</p></div>${cat}<div class="small" style="color:#c8d6be">Volontärportalen</div></section><section class="login-form"><div class="eyebrow">VÄLKOMMEN TILLBAKA</div><h1>En stund för katterna.</h1><p class="muted">Logga in för att se och boka dina veckopass.</p><form id="login"><label>E-post<input name="email" type="email" autocomplete="username" required placeholder="namn@exempel.se"></label><label>Lösenord<input name="password" type="password" autocomplete="current-password" required></label><p class="error" id="login-error" role="alert"></p><button class="primary">Logga in →</button></form><button class="link" id="forgot-password">Glömt lösenord?</button></section></div>`;
 $('#forgot-password').onclick=forgotPassword;
 $('#login').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{state=await api('login','POST',Object.fromEntries(new FormData(e.target)));render()}catch(err){$('#login-error').textContent=err.message;btn.disabled=false}}}
function render(){if(!state)return login();const admin=isAdmin(state.user),days=week(),slots=state.slots.filter(s=>days.includes(s.date)),mine=state.slots.filter(s=>s.mine&&!s.cancelled&&!past(s));
 app.innerHTML=`<div class="layout"><aside class="sidebar">${brand}<div class="eyebrow">VOLONTÄRPORTALEN</div><nav class="nav">${[['schedule','◷','Veckoschema'],['mine','♡','Mina bokningar'],['info','ⓘ','Volontärinfo'],...(admin?[['admin','☷','Administration']]:[]),['account','⚙','Mitt konto']].map(([key,icon,label])=>`<button data-view="${key}" class="${view===key?'active':''}">${icon} &nbsp; ${label}</button>`).join('')}</nav><div class="side-bottom"><div class="profile"><span class="avatar">${esc(state.user.name.charAt(0))}</span><div><strong>${esc(state.user.name)}</strong><div class="small">${roleLabel(state.user.role)}</div></div></div><button class="link" data-action="logout">Logga ut ↗</button></div></aside><main><div class="topline"><span class="eyebrow">TILLSAMMANS FÖR KATTERNA</span><span class="badge">Volontärportalen</span></div>${upcomingReminders()}${view==='info'?volunteerInfo():view==='schedule'?`<section class="hero"><div class="hero-copy"><div class="eyebrow">VARJE PASS GÖR SKILLNAD</div><h1>Lite av din tid.<br>Mycket för en katt.</h1><p class="muted">Hitta en stund som passar dig. Vi tar hand om katterna tillsammans.</p></div>${cat}</section><div class="stats"><div class="stat"><span>Dina kommande pass</span><b>${mine.length.toString().padStart(2,'0')}</b></div><div class="stat"><span>Pass som behöver fler denna vecka</span><b>${slots.filter(s=>!past(s)&&!s.cancelled&&!staffed(s)).length}</b></div><div class="stat"><span>Pass med minst två anmälda</span><b>${slots.filter(staffed).length}<small class="muted"> / ${slots.filter(s=>!s.cancelled).length}</small></b></div></div><div class="toolbar"><div><h2>Veckans pass</h2><span class="small" id="refresh-status" role="status">Uppdateras automatiskt · </span><button class="link" id="refresh-schedule">Uppdatera nu</button><span class="small">${fmt(days[0])} – ${fmt(days[6],{day:'numeric',month:'long',year:'numeric'})}</span></div><div class="weeknav"><button data-action="prev" aria-label="Föregående vecka">←</button><b>Vecka ${weekNumber(days[0])}</b><button data-action="next" aria-label="Nästa vecka">→</button><button data-action="today">Idag</button></div></div><div class="toolbar"><div class="filters">${[['all','Alla pass'],['free','Behöver fler'],['mine','Mina pass']].map(([k,l])=>`<button data-filter="${k}" class="${filter===k?'selected':''}">${l}</button>`).join('')}</div><span class="small">Alla tider är lokala · Minst 2 per pass</span></div><div class="week-grid">${days.map(date=>`<section><div class="day-head ${date===dateStr(new Date())?'today':''}"><span>${fmt(date,{weekday:'short'})}</span><strong>${new Date(date+'T12:00').getDate()}</strong></div>${slots.filter(s=>s.date===date&&(filter==='all'||filter==='mine'&&s.mine||filter==='free'&&!s.cancelled&&!staffed(s)&&!past(s))).map(s=>`<article class="slot ${s.start>='12:00'?'evening':''} ${s.mine?'booked':''} ${s.cancelled?'cancelled':''} ${needsStaffing(s)?'understaffed':''}"><span class="time">${esc(s.start)} – ${esc(s.end)}</span><h3>${esc(s.title)}</h3>${s.extra_info?`<p class="slot-extra">${esc(s.extra_info)}</p>`:''}<span class="spots">${esc(staffing(s))}${s.mine&&!s.cancelled?' · ✓ Du är bokad':''}</span>${admin?`<p class="people">${state.bookings.filter(b=>b.slot_id===s.id).map(b=>esc(b.name)).join(', ')||'Ingen bokad ännu'}</p>`:''}<button data-slot="${s.id}" ${(past(s)||s.cancelled)&&!admin&&!s.mine?'disabled':''} class="${s.mine?'':'primary'}">${s.cancelled?'Visa inställt pass':s.mine?'Visa bokning':admin?'Hantera pass':past(s)?'Passerat':'Boka pass'}</button></article>`).join('')||'<p class="small" style="text-align:center">Inga pass</p>'}</section>`).join('')}</div><div class="legend"><span><i class="dot"></i>Morgonpass</span><span><i class="dot orange"></i>Eftermiddags- / kvällspass</span><span><i class="dot red"></i>Rött: färre än 2 anmälda inom 7 dagar</span></div><div class="notice">Minst två volontärer behövs per pass. Rekommenderat högst 7 per pass; fler kan boka efter extra bekräftelse. Söndagar 18–20 träffas socialiseringsgruppen. Första söndagen i månaden är det öppet hus och passet 16–18 är inställt. Avboka senast 24 timmar före passet. Vid senare förhinder, kontakta katthemmets administratör.</div>`:view==='mine'?`<h1>Mina bokningar</h1><p class="muted">Dina kommande stunder på katthemmet.</p><div class="panel ${state.user.green?'experienced-volunteer':''}"><strong>${state.user.completed_shifts} genomförda pass</strong>${state.user.green?isAdmin(state.user)?' · Grön – '+roleLabel(state.user.role):' · Grön volontär':''}<p class="small">Avslutade bokade pass, exklusive inställda pass.</p></div><div class="panel">${mine.length?mine.map(s=>`<div class="list-row"><div><strong>${fmt(s.date,{weekday:'long',day:'numeric',month:'long'})}</strong><p>${esc(s.title)} · ${s.start}–${s.end}</p></div><div class="actions"><button data-slot="${s.id}">Visa bokning</button>${calendarLink(s)}</div></div>`).join(''):'<div class="empty">Du har inga kommande pass ännu.<br>Boka ditt första pass i veckoschemat.</div>'}</div>${cancelledBookings()}`:view==='admin'&&admin?`<h1>En trygg vardag, tillsammans.</h1><p class="muted">Planera passen och håll koll på volontärerna.</p><div class="actions"><button class="primary" data-action="new-slot">+ Skapa pass</button><button data-action="new-user">+ Lägg till konto</button><button data-action="new-event">+ Skapa händelse</button>${isSuperAdmin(state.user)?'<button data-action="new-admin">+ Skapa styrelsekonto</button>':''}</div><section class="panel"><h2>Importera och exportera CSV</h2><p class="small">Importera nya volontärer eller exportera schemat och bokningarna.</p><div class="actions"><button class="primary" data-action="import-users">↑ Importera från CSV</button><a class="export-link" href="/api/export">↓ Exportera till CSV</a></div><p class="small">Import: namn, e-post, lösenord och valfritt grönmarkering. Du får förhandsgranska innan kontona skapas.</p></section>${adminWarnings()}${eventList()}<div class="panel"><h2>Volontärer & styrelse</h2><p class="small">Bokade pass räknas som genomförda efter sluttiden. Inställda pass räknas inte. Styrelse och superadmin grönmarkeras alltid. Volontärer grönmarkeras av admin eller automatiskt efter fler än 15 pass.</p>${state.users.map(u=>`<div class="list-row ${u.green?'experienced-volunteer':''}"><div><strong>${esc(u.name)}</strong> <span class="badge">${u.role!=='volunteer'?roleLabel(u.role):u.active?'Aktiv':'Inaktiv'}</span><p class="small">${esc(u.email)} · <strong>${u.completed_shifts} genomförda pass</strong>${u.green?isAdmin(u)?' · Grön – '+roleLabel(u.role):u.green_manual?' · Grönmarkerad av admin':' · Grön – över 15 pass':''} · ${state.bookings.filter(b=>b.user_id===u.id&&state.slots.some(s=>s.id===b.slot_id&&!past(s))).length} kommande pass</p></div><div class="actions">${u.id!==state.user.id&&canManageAccount(state.user,u)?`<button data-reset-password="${u.id}">Byt lösenord</button>`:''}${isSuperAdmin(state.user)&&u.id!==state.user.id?`<button data-role-user="${u.id}" data-role="${u.role==='admin'?'volunteer':'admin'}">${u.role==='admin'?'Gör till volontär':'Gör till styrelse'}</button>`:''}${isSuperAdmin(state.user)&&u.id!==state.user.id&&u.role!=='superadmin'?`<button data-role-user="${u.id}" data-role="superadmin">Gör till superadmin</button>`:''}${u.role==='volunteer'?`<button data-green-user="${u.id}" data-green="${u.green_manual?'false':'true'}">${u.green_manual?'Ta bort manuell grönmarkering':'Grönmarkera'}</button>`:''}${u.id!==state.user.id&&canManageAccount(state.user,u)?`<button data-user="${u.id}" data-active="${u.active?0:1}">${u.active?'Inaktivera':'Aktivera'}</button>`:''}</div></div>`).join('')}</div><div class="notice">Google Sheets: exportera CSV-filen och importera den i ett kalkylark (avgränsare: semikolon). Automatisk synkning är ännu inte ansluten. Inaktivering blockerar inloggning; befintliga bokningar finns kvar för administratören att hantera.</div>`:`<h1>Mitt konto</h1><p class="muted">${esc(state.user.name)} · ${esc(state.user.email)}</p><div class="panel ${state.user.green?'experienced-volunteer':''}"><strong>${state.user.completed_shifts} genomförda pass</strong>${state.user.green?isAdmin(state.user)?' · Grön – '+roleLabel(state.user.role):' · Grön volontär':''}</div><section class="panel" style="max-width:520px"><h2>Byt lösenord</h2><form id="password-form"><label>Nuvarande lösenord<input name="current" type="password" autocomplete="current-password" required></label><label>Nytt lösenord, minst 10 tecken<input name="password" type="password" minlength="10" maxlength="200" autocomplete="new-password" required></label><button class="primary">Spara lösenord</button></form></section><button style="margin-top:20px" data-action="logout">Logga ut</button>`}<footer>Katthemmet · Tack för att du gör plats för omtanke.</footer></main></div>`;
 app.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});app.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>slotDialog(Number(b.dataset.slot)));
 app.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action;if(a==='prev')offset--;if(a==='next')offset++;if(a==='today')offset=0;if(['prev','next','today'].includes(a)){try{state=await api('state');render()}catch(e){toast(e.message)}}if(a==='logout'){await api('logout','POST');state=null;view='schedule';render()}if(a==='new-slot')newSlot();if(a==='new-event')eventForm();if(a==='new-admin')newUser('admin');if(a==='new-user')newUser();if(a==='import-users')importUsers()});
 app.querySelectorAll('[data-edit-event]').forEach(b=>b.onclick=()=>eventForm(Number(b.dataset.editEvent)));
 app.querySelectorAll('[data-reset-password]').forEach(b=>b.onclick=()=>resetUserPassword(Number(b.dataset.resetPassword)));
 app.querySelectorAll('[data-role-user]').forEach(b=>b.onclick=()=>changeRole(Number(b.dataset.roleUser),b.dataset.role));
 if($('#email-settings'))$('#email-settings').onclick=()=>emailSettingsDialog();
 if($('#send-reminders'))$('#send-reminders').onclick=()=>mutate('reminders/send','POST',{},'E-postpåminnelser för nästa dygn har behandlats.');
 app.querySelectorAll('[data-user]').forEach(b=>b.onclick=()=>mutate('users/'+b.dataset.user,'PATCH',{active:Number(b.dataset.active)},'Kontot har uppdaterats.'));
 app.querySelectorAll('[data-green-user]').forEach(b=>b.onclick=()=>mutate('users/'+b.dataset.greenUser,'PATCH',{green:b.dataset.green==='true'},'Grönmarkeringen har uppdaterats.'));
 if($('#refresh-schedule'))$('#refresh-schedule').onclick=()=>refreshSchedule(true);
 if($('#edit-info'))$('#edit-info').onclick=editVolunteerInfo;
 app.querySelectorAll('[data-checklist-item]').forEach(input=>input.onchange=()=>saveChecklistItem(input));
 if($('#password-form'))$('#password-form').onsubmit=async e=>{e.preventDefault();try{await api('password','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('Lösenordet har ändrats.')}catch(err){toast(err.message)}};
}
function show(html){modal.innerHTML=html;modal.showModal();modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close())}
async function mutate(url,method,data,message){try{state=await api(url,method,data);if(modal.open)modal.close();render();toast(message)}catch(e){if(e.code==='OVERLAPPING_BOOKING'){confirmOverlapDialog(e.message,()=>mutate(url,method,{...data,confirmOverlap:true},message));return}const err=modal.querySelector('.error');if(err)err.textContent=e.message;else toast(e.message)}}
function confirmOverlapDialog(message,onConfirm){show(`<h2>Passens tider överlappar</h2><p class="info-text">${esc(message)}</p><p>Det går bra att delta i båda passen, till exempel morgonpass och öppet hus, om du kan vara kvar.</p><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button class="primary" id="confirm-overlap">Ja, bekräfta överlappningen</button></div>`);$('#confirm-overlap').onclick=async()=>{const button=$('#confirm-overlap');button.disabled=true;try{await onConfirm()}finally{if(button.isConnected)button.disabled=false}}}
function slotDialog(id){
 const s=state.slots.find(x=>x.id===id),admin=isAdmin(state.user),b=state.bookings.find(x=>x.slot_id===id&&x.user_id===state.user.id),canCancel=admin||new Date(s.date+'T'+s.start)-Date.now()>=86400000,ended=new Date(s.date+'T'+s.end)<=new Date();
 show(`<div class="eyebrow">${fmt(s.date,{weekday:'long',day:'numeric',month:'long'})}</div><h2>${esc(s.title)}</h2><p>${s.start}–${s.end} · ${esc(staffing(s))}</p><p class="info-text muted">${esc(s.note)}</p>${s.extra_info?`<section class="notice"><strong>Extra information</strong><p class="info-text">${esc(s.extra_info)}</p></section>`:''}${admin?`<h3>Bokade volontärer</h3>${state.bookings.filter(x=>x.slot_id===id).map(x=>`<div class="list-row"><span>${esc(x.name)}</span>${!s.cancelled?`<button class="danger" data-cancel="${x.id}">Avboka</button>`:''}</div>`).join('')||'<p class="small">Ingen bokad ännu.</p>'}${!past(s)&&!s.cancelled?`<label>Boka åt volontär<select id="book-user">${state.users.filter(u=>u.active&&!state.bookings.some(x=>x.slot_id===id&&x.user_id===u.id)).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><button class="primary" id="admin-book">Boka vald volontär</button>`:''}`:''}<p class="error" role="alert"></p>${b&&!canCancel&&!s.cancelled?'<p class="notice">Mindre än 24 timmar kvar. Kontakta administratören för avbokning.</p>':''}<div class="dialog-actions">${admin&&!ended?'<button id="extra-info">Extra information</button>':''}${admin&&s.kind!=='open_house'&&!ended?`<button id="edit-slot">${s.cancelled?'Boka om':'Ändra / boka om'}</button>${!s.cancelled?'<button class="danger" id="cancel-slot">Ställ in</button>':''}`:''}${calendarLink(s)}<button data-close>Stäng</button>${!admin&&!s.cancelled?(b?`<button class="danger" id="cancel" ${canCancel?'':'disabled'}>Avboka pass</button>`:!past(s)?'<button class="primary" id="book">Bekräfta bokning</button>':''):''}</div>`);
 if($('#book'))$('#book').onclick=()=>bookSlot(id);if($('#cancel'))$('#cancel').onclick=()=>mutate('bookings/'+b.id,'DELETE',null,'Passet är avbokat.');if($('#admin-book'))$('#admin-book').onclick=()=>{const uid=Number($('#book-user').value);if(uid)bookSlot(id,uid);else modal.querySelector('.error').textContent='Ingen bokningsbar volontär vald.'};modal.querySelectorAll('[data-cancel]').forEach(btn=>btn.onclick=()=>mutate('bookings/'+btn.dataset.cancel,'DELETE',null,'Bokningen är borttagen.'));
 if($('#extra-info'))$('#extra-info').onclick=()=>extraInfoForm(id);
 if($('#edit-slot'))$('#edit-slot').onclick=()=>eventForm(id);if($('#cancel-slot'))$('#cancel-slot').onclick=()=>cancelEvent(id);
}
function extraInfoForm(id){const s=state.slots.find(s=>s.id===id);show(`<h2>Extra information på passet</h2><p>${esc(s.title)} · ${fmt(s.date)} · ${s.start}–${s.end}</p><form id="extra-info-form"><label>Extra information<textarea name="extra_info" rows="4" maxlength="1000" placeholder="Till exempel: Volontärsträff kl. 18 – välkommen!">${esc(s.extra_info||'')}</textarea></label><p class="small">Visas för volontärerna i schemat och i passets detaljer. Lämna tomt för att ta bort informationen. Bokade deltagare meddelas via den aktiverade e-postkopplingen.</p><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara extra information</button></div></form>`);$('#extra-info-form').onsubmit=e=>{e.preventDefault();mutate('slots/'+id,'PATCH',Object.fromEntries(new FormData(e.target)),'Passinformationen har sparats.')}}
function newSlot(){show(`<h2>Skapa ett nytt pass</h2><form id="slot-form"><input name="kind" type="hidden" value="regular"><label>Namn<input name="title" value="Morgonpass" required maxlength="100"></label><label>Datum<input name="date" type="date" value="${dateStr(new Date())}" required></label><div class="form-grid"><label>Start<input name="start" type="time" value="08:00" required></label><label>Slut<input name="end" type="time" value="12:00" required></label></div><p class="notice">Minst 2 volontärer behövs. Rekommenderat högst 7, fler kan boka efter bekräftelse. Söndagar 18–20 är socialiseringsgruppen; första söndagens pass 16–18 är inställt.</p><label>Information<textarea name="note" rows="2" maxlength="1000"></textarea></label><label>Extra information (valfritt)<textarea name="extra_info" rows="2" maxlength="1000" placeholder="Till exempel: Volontärsträff kl. 18 – välkommen!"></textarea></label><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Skapa pass</button></div></form>`);$('#slot-form').onsubmit=e=>{e.preventDefault();mutate('slots','POST',Object.fromEntries(new FormData(e.target)),'Passet har skapats.')}}
function newUser(role='volunteer'){show(`<h2>${role==='admin'?'Skapa styrelsekonto':'Lägg till konto'}</h2><p class="muted">Skapa ett konto och lämna inloggningsuppgifterna till volontären personligen.</p><form id="user-form">${isSuperAdmin(state.user)?`<label>Roll<select name="role">${['volunteer','admin','superadmin'].map(value=>`<option value="${value}" ${role===value?'selected':''}>${roleLabel(value)}</option>`).join('')}</select></label>`:'<input name="role" type="hidden" value="volunteer">'}<p class="small">Styrelsen sköter verksamheten. Superadmin hanterar dessutom administratörskonton, behörigheter och systeminställningar.</p><label>Namn<input name="name" required maxlength="100"></label><label>E-post<input name="email" type="email" required></label><label>Tillfälligt lösenord<input name="password" type="password" minlength="10" maxlength="200" autocomplete="new-password" required></label><p class="small">Volontären kan ändra lösenordet under Mitt konto. Inget e-postmeddelande skickas.</p><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Skapa konto</button></div></form>`);$('#user-form').onsubmit=e=>{e.preventDefault();mutate('users','POST',Object.fromEntries(new FormData(e.target)),'Kontot har skapats.')}}

function importUsers(){
 show(`<h2>Importera volontärer</h2><p class="small">UTF-8 CSV, högst 500 volontärer. Rubriker: namn;e-post;lösenord och valfritt grön (ja/nej). Lösenord ska ha 10–200 tecken. Befintliga e-postadresser ger ett fel; inga konton importeras då.</p><pre class="small">namn;e-post;lösenord;grön<br>Exempelperson;namn@exempel.se;BytDetta12345;nej</pre><form id="import-form"><label>CSV-fil<input id="import-file" type="file" accept=".csv,text/csv" required></label><label class="check-label"><input id="import-green" type="checkbox"> Grönmarkera alla i importen</label><p class="small">Utan detta val används kolumnen grön. Lämna inloggningsuppgifterna personligen; ingen e-post skickas.</p><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Förhandsgranska</button></div></form>`);
 $('#import-form').onsubmit=async e=>{
  e.preventDefault();const btn=e.target.querySelector('button.primary');btn.disabled=true;
  try{
   const file=$('#import-file').files[0];if(!file||file.size>500000)throw Error('Välj en CSV-fil på högst 500 kB.');
   const payload={csv:await file.text(),green:$('#import-green').checked};
   const preview=await api('users/import-preview','POST',payload);
   show(`<h2>Importera ${preview.users.length} volontärer?</h2><p>${preview.users.filter(u=>u.green).length} grönmarkeras. Alla nya konton blir volontärer.</p><div class="import-preview">${preview.users.map(u=>`<div class="list-row ${u.green?'experienced-volunteer':''}"><span>${esc(u.name)}<br><span class="small">${esc(u.email)}</span></span>${u.green?'Grön':''}</div>`).join('')}</div><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button id="confirm-import" class="primary">Importera</button></div>`);
   $('#confirm-import').onclick=async()=>{const confirm=$('#confirm-import');confirm.disabled=true;await mutate('users/import','POST',payload,'Volontärerna har importerats.');if(modal.open)confirm.disabled=false};
  }catch(err){modal.querySelector('.error').textContent=err.message;btn.disabled=false}
 };
}


function upcomingReminders(){
 const now=Date.now(),soon=state.slots.filter(s=>s.mine&&!s.cancelled&&new Date(s.date+'T'+s.start)>now&&new Date(s.date+'T'+s.start)-now<=86400000);
 return soon.length?`<section class="notice reminder-notice" role="status"><strong>Påminnelse: dina pass inom nästa dygn</strong>${soon.map(s=>`<p>${esc(s.title)} · ${fmt(s.date)} kl. ${s.start}–${s.end} <button data-slot="${s.id}">Visa bokning</button></p>`).join('')}</section>`:'';
}
function adminWarnings(){
 const inactive=state.users.filter(u=>u.inactive_month),mail=state.email_reminders;
 return `<section class="notice"><h2>Volontärer att följa upp</h2>${inactive.length?inactive.map(u=>`<p><strong>${esc(u.name)}</strong> · ${esc(u.email)} · ${u.last_completed_at?'Senaste genomförda pass: '+new Date(u.last_completed_at).toLocaleDateString('sv-SE'):'Inget genomfört pass sedan registrering för minst en månad sedan'}</p>`).join(''):'<p>Ingen aktiv volontär har varit borta en månad.</p>'}<p class="small">Beräknat från avslutade bokningar, inte bekräftad närvaro. Nya volontärer får en månads starttid.</p></section><section class="notice"><h2>E-post och påminnelser</h2><p>${state.change_notifications?.pending||0} ändringsmejl väntar på utskick${state.change_notifications?.failed?' · '+state.change_notifications.failed+' misslyckade, nytt försök görs automatiskt':''}. Ändringar och inställda pass meddelas till bokade deltagare.</p><p>Påminnelser på sidan visas för egna pass inom nästa dygn.</p><p>${mail?.configured?'E-post aktiverad via '+(mail.provider==='gmail'?'Gmail':'Resend')+': automatiskt inom 24 timmar före passet. '+mail.sent_count+' påminnelser skickade.':'E-post är inte aktiverad. En superadmin kan koppla ett Gmail-konto via E-postinställningar.'}</p>${mail?.last_error?`<p class="error">${esc(mail.last_error)}</p>`:''}${isSuperAdmin(state.user)?'<button id="email-settings">E-postinställningar</button>':''} <button id="send-reminders" ${mail?.configured?'':'disabled'}>Skicka påminnelser för nästa dygn</button></section>`;
}
function changeRole(id,role){const u=state.users.find(u=>u.id===id);show(`<h2>Ändra roll för ${esc(u.name)}?</h2><p>${role==='superadmin'?'Superadmin får hantera administratörskonton, behörigheter och systeminställningar.':role==='admin'?'Styrelsen får hantera den löpande verksamheten, medlemsregistret och kattinformationen.':'Kontot får volontärbehörighet.'}</p><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button class="primary" id="confirm-role">Bekräfta</button></div>`);$('#confirm-role').onclick=()=>mutate('users/'+id,'PATCH',{role},'Rollen har uppdaterats.')}
async function bookSlot(id,userId,confirmOverLimit=false,confirmOverlap=false){
 try{state=await api('bookings','POST',{slotId:id,...(userId?{userId}:{}),confirmOverLimit,confirmOverlap});modal.close();render();toast('Bokningen är klar. Tack för din tid!')}
 catch(e){if(e.code==='RECOMMENDED_LIMIT'){
  show(`<h2>Redan minst 7 anmälda</h2><p>Det rekommenderade taket är 7 personer per pass. Är du säker på att du vill boka ytterligare en person?</p><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button class="primary" id="confirm-over-limit">Ja, boka ändå</button></div>`);
  $('#confirm-over-limit').onclick=()=>bookSlot(id,userId,true,confirmOverlap);
 }else if(e.code==='OVERLAPPING_BOOKING'){confirmOverlapDialog(e.message,()=>bookSlot(id,userId,confirmOverLimit,true))}else{const error=modal.querySelector('.error');if(error)error.textContent=e.message;else toast(e.message)}}
}


function eventList(){const events=state.slots.filter(s=>s.kind==='event'&&new Date(s.date+'T'+s.end)>new Date());return `<section class="panel"><h2>Händelser</h2><p class="small">Lägg in till exempel veterinärbesök. Ändra datum och tid med Boka om; befintliga deltagare följer med.</p>${events.length?events.map(s=>`<div class="list-row"><div><strong>${esc(s.title)}</strong><p class="small">${fmt(s.date)} · ${s.start}–${s.end} · ${s.cancelled?'Inställd':s.booked+' anmälda'}</p></div><div class="actions"><button data-slot="${s.id}">Visa deltagare</button><button data-edit-event="${s.id}">${s.cancelled?'Boka om':'Ändra / boka om'}</button></div></div>`).join(''):'<p class="small">Inga kommande händelser.</p>'}</section>`}
function eventForm(id){
 const s=id?state.slots.find(s=>s.id===id):null;
 show(`<h2>${s?'Ändra / boka om '+(s.kind==='event'?'händelse':'pass'):'Skapa händelse'}</h2><form id="event-form"><input name="kind" type="hidden" value="event"><label>Namn<input name="title" required maxlength="100" value="${esc(s?.title||'Veterinärbesök')}"></label><label>Datum<input name="date" type="date" value="${s?.date||dateStr(new Date())}" required></label><div class="form-grid"><label>Start<input name="start" type="time" value="${s?.start||'13:00'}" required></label><label>Slut<input name="end" type="time" value="${s?.end||'14:00'}" required></label></div><label>Information<textarea name="note" maxlength="1000" rows="3">${esc(s?.note||'')}</textarea></label><label>Extra information (valfritt)<textarea name="extra_info" rows="2" maxlength="1000" placeholder="Till exempel: Volontärsträff kl. 18 – välkommen!">${esc(s?.extra_info||'')}</textarea></label><p class="notice">${s?'Deltagarnas bokningar behålls. Vid överlappande tider behöver du bekräfta ändringen. Berörda deltagare meddelas via e-post när e-post är aktiverad. Ett inställt pass blir bokningsbart igen när du sparar.':'Händelsen visas i schemat och volontärer kan boka sig. Minst 2, rekommenderat högst 7 deltagare.'}</p><p class="error" role="alert"></p><div class="dialog-actions">${s&&!s.cancelled?'<button type="button" id="cancel-event">Ställ in</button>':''}<button type="button" data-close>Avbryt</button><button class="primary">${s?'Spara ändring':'Skapa händelse'}</button></div></form>`);
 $('#event-form').onsubmit=e=>{e.preventDefault();mutate(s?'slots/'+s.id:'slots',s?'PATCH':'POST',Object.fromEntries(new FormData(e.target)),s?'Ändringen har sparats.':'Händelsen har skapats.')};
 if($('#cancel-event'))$('#cancel-event').onclick=()=>cancelEvent(id);
}
function cancelEvent(id){const s=state.slots.find(s=>s.id===id);show(`<h2>Ställa in ${s.kind==='event'?'händelsen':'passet'}?</h2><p>${esc(s.title)} den ${fmt(s.date)} kl. ${s.start}–${s.end}.</p><p>${s.booked} anmälningar behålls i historiken. Passet spärras för nya bokningar och räknas inte som genomfört. Deltagarna meddelas via e-post när e-post är aktiverad.</p><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Behåll ${s.kind==='event'?'händelsen':'passet'}</button><button class="danger" id="confirm-cancel-event">Ställ in</button></div>`);$('#confirm-cancel-event').onclick=()=>mutate('slots/'+id,'PATCH',{cancelled:true},'Passet är inställt.')}


async function emailSettingsDialog(message=''){
 try{
  const settings=await api('email-settings');
  show(`<h2>E-postinställningar – Gmail</h2><p class="small">Aktivera tvåstegsverifiering i Google-kontot och skapa ett applösenord. Använd applösenordet här. <a href="https://support.google.com/mail/answer/185833?hl=sv" target="_blank" rel="noopener noreferrer">Googles instruktioner</a></p><form id="email-settings-form"><label>Gmail-adress<input name="gmail_address" type="email" required maxlength="254" autocomplete="off" value="${esc(settings.gmail_address)}"></label><label>Gmail-applösenord<input name="app_password" type="password" autocomplete="new-password" maxlength="30" ${settings.password_saved?'':'required'} placeholder="${settings.password_saved?'Sparat – lämna tomt för att behålla':'16 tecken från Google'}"></label><p class="small">${settings.password_saved?'Ett applösenord finns sparat. Det visas aldrig igen.':'Applösenordet lagras krypterat på servern.'}</p><label>Sidans webbadress<input name="app_url" type="url" required value="${esc(settings.app_url)}" placeholder="https://katthem.exempel.se"></label><p class="small">Länken som volontärerna ska öppna från påminnelsen. Använd er publika HTTPS-adress vid gemensam drift.</p><label class="check-label"><input name="enabled" type="checkbox" ${settings.enabled?'checked':''}> Aktivera Gmail för påminnelser, ändringsmejl och lösenordsåterställning</label><p class="small">Spara först och skicka ett testmejl. När Gmail sparas ersätter dessa inställningar eventuell Resend-koppling. Avmarkera för att stänga av e-post.</p><p class="error" role="alert"></p><p class="small" id="email-status" role="status">${esc(message)}</p><div class="dialog-actions"><button type="button" data-close>Stäng</button><button class="primary">Spara inställningar</button></div></form><hr><form id="email-test-form"><h3>Skicka testmejl</h3><label>Mottagaradress<input name="to" type="email" required value="${esc(state.user.email.endsWith('.local')?'':state.user.email)}" placeholder="din-adress@gmail.com"></label><p class="small">Testet använder sparade Gmail-inställningar och fungerar även innan automatiska påminnelser aktiverats.</p><button ${settings.password_saved?'':'disabled'}>Skicka testmejl</button></form>`);
  $('#email-settings-form').onsubmit=async e=>{
   e.preventDefault();const form=e.target,button=form.querySelector('button.primary');button.disabled=true;
   try{const values=Object.fromEntries(new FormData(form));await api('email-settings','PUT',{gmail_address:values.gmail_address,app_password:values.app_password,app_url:values.app_url,enabled:form.elements.enabled.checked});form.elements.app_password.value='';state=await api('state');render();await emailSettingsDialog('Inställningarna är sparade. Skicka gärna ett testmejl.')}catch(err){modal.querySelector('.error').textContent=err.message;button.disabled=false}
  };
  $('#email-test-form').onsubmit=async e=>{
   e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;modal.querySelector('.error').textContent='';$('#email-status').textContent='Skickar testmejl…';
   try{await api('email-settings/test','POST',Object.fromEntries(new FormData(e.target)));$('#email-status').textContent='Testmejlet har skickats. Kontrollera inkorgen och skräpposten.'}catch(err){$('#email-status').textContent='';modal.querySelector('.error').textContent=err.message}finally{button.disabled=false}
  };
 }catch(err){toast(err.message)}
}


function resetUserPassword(id){
 const u=state.users.find(u=>u.id===id);
 show(`<h2>Byt lösenord för ${esc(u.name)}</h2><p class="small">${esc(u.email)}</p><form id="reset-user-password"><label>Nytt lösenord<input name="password" type="password" minlength="10" maxlength="200" autocomplete="new-password" required></label><label>Bekräfta nytt lösenord<input name="confirm" type="password" minlength="10" maxlength="200" autocomplete="new-password" required></label><p class="notice">Alla inloggningar för kontot avslutas. Lämna det nya lösenordet till personen direkt. Inget mejl skickas. Personen kan sedan byta lösenord under Mitt konto.</p><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara nytt lösenord</button></div></form>`);
 $('#reset-user-password').onsubmit=async e=>{
  e.preventDefault();const values=Object.fromEntries(new FormData(e.target));
  if(values.password!==values.confirm){modal.querySelector('.error').textContent='Lösenorden stämmer inte överens.';return}
  const button=e.target.querySelector('button.primary');button.disabled=true;
  await mutate('users/'+id+'/password','POST',{password:values.password},'Lösenordet har ändrats och kontots inloggningar har avslutats.');
  if(modal.open)button.disabled=false;else modal.innerHTML='';
 };
}

const infoFields=[['location','Adress och hitta hit']];
function volunteerInfo(){const info=state.volunteer_info||{};return `<h1>Volontärinformation</h1><p class="muted">Praktisk information inför ditt pass.</p>${isAdmin(state.user)?'<button id="edit-info">Redigera information</button>':''}${infoFields.map(([key,title])=>`<section class="panel"><h2>${title}</h2><p class="info-text">${info[key]?esc(info[key]):'Information kommer. Administratören fyller i uppgifterna här.'}</p></section>`).join('')}${volunteerChecklist()}${portalManual()}`}
const checklistSaving=new Set();
function volunteerChecklist(){const checklist=state.checklist;if(state.user.green||!checklist)return '';const checked=new Set(checklist.checked_items),total=checklist.groups.reduce((n,g)=>n+g.items.length,0);return `<section class="panel onboarding-checklist"><h2>Min första tid på katthemmet</h2><p>Gå igenom checklistan tillsammans med en erfaren volontär. Kryssa i det du har gått igenom; du kan ta bort ett kryss om du vill återkomma till punkten. Arbetsinstruktionerna finns analogt på katthemmet.</p><p class="small"><strong id="checklist-count">${checked.size} av ${total} punkter klara</strong> · <span id="checklist-status" role="status" aria-live="polite">Dina personliga kryss sparas automatiskt.</span></p>${checklist.groups.map(group=>`<fieldset><legend>${esc(group.title)}</legend>${group.items.map(item=>`<label class="check-label checklist-item"><input type="checkbox" data-checklist-item="${esc(item.id)}" ${checked.has(item.id)?'checked':''}><span>${esc(item.text)}</span></label>`).join('')}</fieldset>`).join('')}</section>`}
async function saveChecklistItem(input){const id=input.dataset.checklistItem,checked=input.checked,userId=state.user.id;checklistSaving.add(id);input.disabled=true;if($('#checklist-status'))$('#checklist-status').textContent='Sparar…';try{await api('checklist','PATCH',{item_id:id,checked});if(state?.user.id!==userId)return;const items=new Set(state.checklist.checked_items);if(checked)items.add(id);else items.delete(id);state.checklist.checked_items=[...items];const total=state.checklist.groups.reduce((n,g)=>n+g.items.length,0);if($('#checklist-count'))$('#checklist-count').textContent=`${items.size} av ${total} punkter klara`;if($('#checklist-status'))$('#checklist-status').textContent='Dina kryss är sparade.'}catch(err){input.checked=!checked;if($('#checklist-status'))$('#checklist-status').textContent='Kunde inte spara. Försök igen.';toast(err.message)}finally{checklistSaving.delete(id);input.disabled=false;if(checklistSaving.size&&$('#checklist-status'))$('#checklist-status').textContent='Sparar…'}}
function portalManual(){
 const admin=isAdmin(state.user),superadmin=isSuperAdmin(state.user);
 const chapters=[
  ['Hitta rätt i schemat',[
   'Öppna Veckoschema. Byt vecka med pilarna och använd Idag för att komma tillbaka till aktuell vecka.',
   'Välj Alla pass, Behöver fler eller Mina pass. Varje pass visar tid och antal anmälda. Minst två volontärer behövs; sju är rekommenderat högsta antal. Pass inom de närmaste sju dagarna markeras röda om färre än två är anmälda. Din egen bokning visas fortfarande med texten Du är bokad.',
   'Ordinarie pass fylls på automatiskt 42 dagar framåt. Schemat uppdateras var 30:e sekund när fliken är synlig. Uppdatera nu hämtar det senaste läget direkt.'
  ]],
  ['Färgerna på passen',[
   'Rött betyder att passet ligger inom de närmaste sju dagarna och har färre än två anmälda. Här behövs fler volontärer. Antalet som saknas står på passkortet.',
   'Den röda markeringen försvinner när minst två personer är anmälda. Inställda och redan påbörjade pass markeras inte röda.',
   'Grön kant visar morgonpass och orange kant visar eftermiddags- och kvällspass. Röd bemanningsmarkering går före dessa tidsfärger.',
   'Ljusgrön bakgrund visar att du själv är bokad. Om ditt pass är rött står det fortfarande Du är bokad på kortet. Kontrollera alltid texten och antalet anmälda, inte bara färgen.'
  ]],
  ['Boka ett pass',admin?[
   'Öppna ett framtida aktivt pass med Hantera pass eller Visa bokning.',
   'Under Boka åt volontär väljer du personen som ska delta. Välj ditt eget namn om du själv ska delta och klicka på Boka vald volontär.',
   'Om tiderna överlappar en annan bokning visas en fråga. Bekräfta om personen kan delta i båda passen. Från den åttonde deltagaren krävs en extra bekräftelse.'
  ]:[
   'Öppna ett framtida aktivt pass med Boka pass och läs informationen i rutan.',
   'Klicka på Bekräfta bokning. Kontrollera att passet visas under Mina bokningar.',
   'Om du redan har ett pass som överlappar visas tiderna och du får bekräfta att du vill boka ändå, till exempel morgonpass och öppet hus. Om minst sju redan är anmälda behöver du bekräfta en extra gång.'
  ]],
  ['Mina bokningar och kalendern',[
   'Öppna Mina bokningar för att se dina kommande pass. Visa bokning öppnar informationen om passet.',
   'Lägg till i kalender hämtar en kalenderfil som du kan öppna i din kalenderapp. Filen använder svensk tidszon.',
   'Kalenderfilen är en kopia. Flyttas eller ställs passet in uppdateras inte kalenderappen automatiskt. Kontrollera därför alltid den aktuella bokningen i portalen.',
   'Kommande inställda pass som du varit bokad på visas separat under Inställda pass.'
  ]],
  ['Avboka vid förhinder',admin?[
   'Öppna passet i schemat. Under Bokade volontärer klickar du på Avboka vid rätt person. Detta tar bort just den personens bokning.',
   'Styrelse och superadmin kan hjälpa till med sena avbokningar. Kontrollera att rätt person och pass är valt.',
   'Ska hela passet ställas in använder du Ställ in i stället. Då behålls deltagarna i historiken och ändringsmejl köas.'
  ]:[
   'Öppna passet under Mina bokningar och välj Avboka pass.',
   'Du kan själv avboka fram till 24 timmar före starten. Vid senare förhinder behöver du kontakta den som administrerar schemat.',
   'Kontrollera efter avbokningen att passet inte längre finns bland dina kommande bokningar.'
  ]],
  ['Mitt konto och glömt lösenord',[
   'Under Mitt konto kan du byta lösenord. Ange ditt nuvarande lösenord och ett nytt med minst tio tecken.',
   'Har du glömt lösenordet väljer du Glömt lösenord? på inloggningssidan och anger din e-postadress. Återställningslänken gäller i 30 minuter och kan användas en gång.',
   'Återställningsmejl kräver att e-post är aktiverad. Kontrollera skräpposten och be annars om hjälp med lösenordet.',
   'Använd Logga ut när du är klar, särskilt på en delad dator. På mobil finns knappen under Mitt konto.'
  ]]
 ];
 if(admin)chapters.push(
  ['Skapa, ändra och ställa in pass',[
   'Under Administration väljer du Skapa pass för ett vanligt pass eller Skapa händelse för exempelvis ett veterinärbesök. Fyll i namn, datum, start, slut och information.',
   'Öppna passet och välj Extra information för att lägga till exempelvis Volontärsträff. Informationen visas i schemat, passets detaljer och nya kalenderfiler. Detta fungerar även för öppet hus.',
   'Öppna ett befintligt pass och välj Ändra / boka om. Deltagarnas bokningar följer med. Om den nya tiden överlappar deltagarnas andra bokningar visas vilka som berörs. Du behöver bekräfta innan flytten sparas.',
   'Ställ in spärrar nya bokningar och påminnelser men behåller passet och deltagarna i historiken. Ett inställt pass kan återaktiveras med Boka om.',
   'Avslutade pass kan inte ändras. Öppet hus skapas automatiskt och ligger fast första söndagen i månaden 11–15. Passet 16–18 är inställt den dagen.',
   'Vid ändring eller inställning köas mejl till aktiva bokade deltagare. Utskick kräver aktiverad e-post. Administration visar väntande och misslyckade ändringsmejl.'
  ]],
  ['Hantera volontärkonton',[
   'I Administration väljer du Lägg till konto. Ange namn, e-post och ett tillfälligt lösenord. Lämna inloggningsuppgifterna till personen direkt; inget välkomstmejl skickas.',
   'Byt lösenord i kontolistan sätter ett nytt lösenord åt en volontär och avslutar personens befintliga inloggningar. Personen kan sedan byta det under Mitt konto.',
   'Inaktivera stoppar inloggning men tar inte bort befintliga bokningar. Gå därför igenom kommande bokningar när ett konto inaktiveras.',
   'Grönmarkera används för manuell markering. Volontärer blir också automatiskt gröna efter fler än 15 avslutade bokade pass. Antalet bygger på bokningar, inte registrerad närvaro.',
   'Styrelsen hanterar volontärkonton. Superadmin hanterar även styrelse- och superadminkonton samt ändringar av roller.'
  ]],
  ['Import, export och uppföljning',[
   'Importera från CSV låter dig förhandsgranska nya volontärer innan kontona skapas. Använd rubrikerna namn, e-post, lösenord och valfritt grön. Lösenord krävs på varje rad.',
   'Exportera till CSV hämtar schema och bokningar. Filen använder semikolon och kan importeras i ett kalkylark.',
   'Volontärer att följa upp visar aktiva volontärer utan ett avslutat bokat pass under en månad. Uppgiften är ett stöd för kontakt och bygger inte på bekräftad närvaro.',
   'Under E-post och påminnelser kan du se utskicksstatus och starta en kontroll av påminnelser för nästa dygn. Superadmin sköter själva e-postinställningarna.'
  ]],
  ['Redigera adress',[
   'Öppna Volontärinfo och välj Redigera information.',
   'Fyll i Adress och hitta hit och klicka på Spara. Texten visas för inloggade användare.',
   'Den här manualen anpassas automatiskt efter rollen. De praktiska rutinerna och viktiga instruktionerna finns analogt på katthemmet.'
  ]]
 );
 if(superadmin)chapters.push(
  ['Superadmin: roller och styrelsekonton',[
   'Välj Skapa styrelsekonto eller Lägg till konto i Administration. I rollistan kan du välja Volontär, Styrelse eller Superadmin.',
   'Gör till styrelse, Gör till volontär och Gör till superadmin ändrar en annan persons behörighet efter bekräftelse. Välj rollen som motsvarar personens uppdrag.',
   'Du kan hantera styrelsekonton och deras lösenord. Din egen roll eller aktivering kan inte ändras i kontolistan; ditt eget lösenord byter du under Mitt konto.'
  ]],
  ['Superadmin: aktivera och kontrollera e-post',[
   'Öppna Administration, E-post och påminnelser, E-postinställningar. Ange Gmail-adress, ett Google-applösenord och portalens publika webbadress.',
   'Spara inställningarna och använd Skicka testmejl för att kontrollera leveransen. Aktivera därefter Gmail för påminnelser, ändringsmejl och lösenordsåterställning.',
   'Ett tomt applösenordsfält behåller det sparade lösenordet. Byte av Gmail-adress kräver ett nytt applösenord.',
   'Kontrollera väntande och misslyckade utskick i Administration. Appen behöver vara igång för att behandla kön och göra nya försök.'
  ]]
 );
 const title=superadmin?'Manual för superadmin':admin?'Manual för styrelsen':'Manual för volontärer';
 return `<section class="panel portal-manual"><h2>${title}</h2><p class="muted">Så använder du volontärportalen. Öppna ett avsnitt för stegvisa instruktioner.</p>${chapters.map(([heading,steps])=>`<details><summary>${esc(heading)}</summary><ol>${steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol></details>`).join('')}</section>`;
}

function editVolunteerInfo(){show(`<h2>Volontärinformation</h2><p class="small">Visas för inloggade volontärer. Lämna fält tomma tills informationen är klar.</p><form id="info-form">${infoFields.map(([key,title])=>`<label>${title}<textarea name="${key}" rows="4" maxlength="4000">${esc(state.volunteer_info?.[key]||'')}</textarea></label>`).join('')}<p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara</button></div></form>`);$('#info-form').onsubmit=e=>{e.preventDefault();mutate('volunteer-info','PUT',Object.fromEntries(new FormData(e.target)),'Informationen har sparats.')}}
function calendarLink(s){const b=state.bookings.find(b=>b.slot_id===s.id&&b.user_id===state.user.id);return b&&!s.cancelled?`<a class="export-link" title="Kalenderfilen är en kopia och uppdateras inte automatiskt vid ändringar." href="/api/bookings/${b.id}/calendar">Lägg till i kalender</a>`:''}
function cancelledBookings(){const slots=state.slots.filter(s=>s.mine&&s.cancelled&&new Date(s.date+'T'+s.end)>new Date());return slots.length?`<section class="panel"><h2>Inställda pass</h2>${slots.map(s=>`<div class="list-row"><div><strong>${esc(s.title)}</strong><p>${fmt(s.date)} · ${s.start}–${s.end} · Inställt</p></div><button data-slot="${s.id}">Visa information</button></div>`).join('')}</section>`:''}
function forgotPassword(){show(`<h2>Glömt lösenord?</h2><p>Ange din e-postadress för att få en återställningslänk. Länken gäller i 30 minuter.</p><form id="forgot-form"><label>E-post<input name="email" type="email" autocomplete="username" maxlength="254" required></label><p class="error" role="alert"></p><p id="reset-status" role="status"></p><div class="dialog-actions"><button type="button" data-close>Stäng</button><button class="primary">Skicka länk</button></div></form>`);$('#forgot-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('.primary');button.disabled=true;try{const result=await api('password-reset/request','POST',Object.fromEntries(new FormData(e.target)));$('#reset-status').textContent=result.message}catch(err){modal.querySelector('.error').textContent=err.message}finally{button.disabled=false}}}
function resetPassword(token){show(`<h2>Välj nytt lösenord</h2><form id="reset-form"><label>Nytt lösenord<input name="password" type="password" autocomplete="new-password" minlength="10" maxlength="200" required></label><label>Bekräfta lösenord<input name="confirm" type="password" autocomplete="new-password" minlength="10" maxlength="200" required></label><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara lösenord</button></div></form>`);$('#reset-form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target)),button=e.target.querySelector('.primary');if(values.password!==values.confirm){modal.querySelector('.error').textContent='Lösenorden stämmer inte överens.';return}button.disabled=true;try{await api('password-reset/confirm','POST',{token,password:values.password});modal.close();state=null;login();toast('Lösenordet har ändrats. Logga in med ditt nya lösenord.')}catch(err){modal.querySelector('.error').textContent=err.message;button.disabled=false}}}
let refreshing=false;
async function refreshSchedule(manual=false){
 if(!state||refreshing||modal.open||checklistSaving.size||document.visibilityState==='hidden')return;
 refreshing=true;const version=mutationVersion;
 try{const fresh=await api('state');if(!state||modal.open||version!==mutationVersion)return;state=fresh;if(['schedule','mine'].includes(view)){const scroll=window.scrollY;render();window.scrollTo(0,scroll)}if(manual)toast('Schemat är uppdaterat.')}catch(err){if(manual)toast(err.message);else if($('#refresh-status'))$('#refresh-status').textContent='Kunde inte uppdatera · '}
 finally{refreshing=false}
}
setInterval(()=>refreshSchedule(),30000);
window.addEventListener('focus',()=>refreshSchedule());
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshSchedule()});
let resetLinkActive=false;
function openResetLink(){const token=new URLSearchParams(window.location.hash.slice(1)).get('reset');if(!token)return false;resetLinkActive=true;mutationVersion++;history.replaceState(null,'',window.location.pathname);state=null;view='schedule';login();if(modal.open)modal.close();resetPassword(token);return true}
window.addEventListener('hashchange',openResetLink);
if(!openResetLink())api('state').then(s=>{if(!resetLinkActive){state=s;render()}}).catch(()=>{if(!resetLinkActive)login()});
